export function projectAssetUsage(project){const users=new Map();const add=(id,map,kind)=>{if(!id)return;let row=users.get(id);if(!row){row={id,maps:new Set(),kinds:new Set(),count:0};users.set(id,row);}row.maps.add(map.name);row.kinds.add(kind);row.count++;};for(const map of project.maps){for(const [layer,cells]of Object.entries(map.layers))for(const cell of cells||[])add(cell?.a,map,layer+' tiles');for(const o of map.objects)add(o.assetId,map,'objects');for(const o of map.fieldObjects||[])add(o.assetId,map,'HM objects');if(map.reference)add(map.reference.assetId,map,'reference');}return[...users.values()].map(r=>({...r,maps:[...r.maps],kinds:[...r.kinds]}));}
export function referenceReport(api){const rows=projectAssetUsage(api.project()),esc=api.esc;api.modal('Asset usage',`<p>Known uses in this project. Editing a shared source image affects every listed placement. Native sprite palettes have separate sharing controls in the sprite editor.</p><input id="usageSearch" type="search" placeholder="Find asset or map"><div id="usageRows"></div>`);const search=document.querySelector('#usageSearch'),target=document.querySelector('#usageRows');const draw=()=>{const query=search.value.toLowerCase();target.innerHTML=rows.filter(r=>(r.id+' '+r.maps.join(' ')).toLowerCase().includes(query)).slice(0,100).map(r=>`<article class="note-card"><b>${esc(api.asset(r.id)?.name||r.id)}</b><p>${r.count} placements · ${esc(r.kinds.join(', '))}</p><small>${esc(r.maps.join(', '))}</small></article>`).join('')||'<p>No matching placed assets.</p>';};search.oninput=draw;draw();}
